-- Exact repeated metadata, never repeated occurrence weights.
-- Generated by src/vane/raw/generate-groups.py. Applied history is unchanged.
-- Every full UUID/opaque ID and raw_id remains one actual physical row.


DROP TRIGGER vane_raw_insert;

DROP TRIGGER vane_raw_update;

DROP TRIGGER vane_raw_delete;

DROP TRIGGER vane_raw_analytics_delete;

DROP TRIGGER vane_raw_analytics_update;

DROP TRIGGER vane_raw_context_gc;

DROP TRIGGER vane_visit_raw_delete;

DROP TRIGGER vane_visit_raw_rewrite;

DROP TRIGGER vane_visit_raw_rewritten;

DROP TRIGGER vane_visit_rebuild_chain;

DROP TRIGGER vane_visit_details_insert;

DROP TRIGGER vane_visit_details_update;

DROP TRIGGER vane_visit_details_delete;

DROP TRIGGER vane_visit_perf_context_before;

DROP TRIGGER vane_visit_perf_context_after;

DROP TRIGGER vane_visit_append;

DROP TRIGGER vane_visit_detail_change;

DROP TRIGGER vane_visit_raw_insert;

DROP TRIGGER vane_visit_raw_bulk_insert;

DROP TRIGGER vane_raw_analytics_insert;

DROP VIEW vane_events;

DROP VIEW vane_visit_raw;

ALTER TABLE vane_raw_events RENAME TO vane_raw_occurrences;
CREATE TABLE vane_raw_groups(
 group_id INTEGER PRIMARY KEY,context INTEGER NOT NULL REFERENCES vane_raw_contexts(context),
 at_offset INTEGER,visit_id INTEGER
);
CREATE UNIQUE INDEX vane_raw_groups_unique ON vane_raw_groups(context,(at_offset IS NULL),coalesce(at_offset,0),(visit_id IS NULL),coalesce(visit_id,0));
CREATE INDEX vane_raw_groups_context_time ON vane_raw_groups(context,at_offset);
CREATE INDEX vane_raw_groups_visit ON vane_raw_groups(visit_id) WHERE visit_id IS NOT NULL;
INSERT INTO vane_raw_groups(context,at_offset,visit_id)
 SELECT DISTINCT context,at_offset,visit_id FROM vane_raw_occurrences;
-- ADD COLUMN cannot declare a non-null REFERENCES column on populated SQLite
-- tables. Integrity triggers below enforce non-null; the FK enforces existence.
ALTER TABLE vane_raw_occurrences ADD COLUMN group_id INTEGER REFERENCES vane_raw_groups(group_id);


UPDATE vane_raw_occurrences SET group_id=(SELECT group_id FROM vane_raw_groups g WHERE g.context=vane_raw_occurrences.context AND (g.at_offset IS NULL)=(vane_raw_occurrences.at_offset IS NULL) AND coalesce(g.at_offset,0)=coalesce(vane_raw_occurrences.at_offset,0) AND (g.visit_id IS NULL)=(vane_raw_occurrences.visit_id IS NULL) AND coalesce(g.visit_id,0)=coalesce(vane_raw_occurrences.visit_id,0));

DROP INDEX vane_raw_events_context_time;
DROP INDEX vane_raw_events_visit;
ALTER TABLE vane_raw_occurrences DROP COLUMN context;
ALTER TABLE vane_raw_occurrences DROP COLUMN at_offset;
ALTER TABLE vane_raw_occurrences DROP COLUMN visit_id;
CREATE INDEX vane_raw_occurrences_group ON vane_raw_occurrences(group_id);
CREATE VIEW vane_raw_events AS SELECT e.raw_id,e.site,e.token,g.context,g.at_offset,g.visit_id
 FROM vane_raw_occurrences e JOIN vane_raw_groups g ON g.group_id=e.group_id;


CREATE VIEW vane_events AS SELECT   CASE   WHEN typeof(e.token)='blob' THEN s.site_id||':'||substr(lower(hex(substr(e.token,1,16))),1,8)||'-'||substr(lower(hex(substr(e.token,1,16))),9,4)||'-'||substr(lower(hex(substr(e.token,1,16))),13,4)||'-'||substr(lower(hex(substr(e.token,1,16))),17,4)||'-'||substr(lower(hex(substr(e.token,1,16))),21,12)||CAST(substr(e.token,17) AS TEXT) ELSE e.token   END   AS id,s.site_id AS site_id,c.day AS day,c.kind AS kind,json_extract(c.dimensions,'$[0]') AS path,json_extract(c.dimensions,'$[1]') AS source,json_extract(c.dimensions,'$[2]') AS campaign,json_extract(c.dimensions,'$[22]') AS consent,json_extract(c.dimensions,'$[23]') AS sample_rate,json_extract(c.dimensions,'$[24]') AS import_job,  CASE   WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value   END   AS visitor,e.at_offset+coalesce(unixepoch(c.day)*1000,0) AS at,d.engaged_at AS engaged_at,d.scroll AS scroll,json_extract(c.dimensions,'$[4]') AS device,json_extract(c.dimensions,'$[5]') AS browser,json_extract(c.dimensions,'$[6]') AS browser_version,json_extract(c.dimensions,'$[7]') AS os,json_extract(c.dimensions,'$[8]') AS os_version,json_extract(c.dimensions,'$[9]') AS screen,json_extract(c.dimensions,'$[20]') AS search,json_extract(c.dimensions,'$[3]') AS hostname,json_extract(c.dimensions,'$[12]') AS utm_source,json_extract(c.dimensions,'$[13]') AS utm_medium,json_extract(c.dimensions,'$[14]') AS utm_term,json_extract(c.dimensions,'$[15]') AS utm_content,json_extract(c.dimensions,'$[25]') AS paid_click,json_extract(c.dimensions,'$[26]') AS query,json_extract(c.dimensions,'$[10]') AS channel,json_extract(c.dimensions,'$[11]') AS referrer,d.lcp AS lcp,d.inp AS inp,d.cls AS cls,d.load_ms AS load_ms,json_extract(c.dimensions,'$[16]') AS country,json_extract(c.dimensions,'$[17]') AS region,json_extract(c.dimensions,'$[18]') AS city,json_extract(c.dimensions,'$[19]') AS metro_code,  CASE   WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value   END   AS consented_visitor,c.consented_created_at AS consented_created_at,c.consented_expires_at AS consented_expires_at,json_extract(c.dimensions,'$[21]') AS transport,e.raw_id AS _raw_id FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context JOIN vane_raw_sites s ON s.site=e.site LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor LEFT JOIN vane_raw_details d ON d.raw_id=e.raw_id;

CREATE VIEW vane_visit_raw AS SELECT e.raw_id,e.site,e.context,e.token,e.visit_id,e.at_offset,c.day,c.kind,c.visitor,
 s.site_id,e.at_offset+unixepoch(c.day)*1000 AS at,d.engaged_at,d.scroll,  CASE   WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||(  CASE   WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value   END  ) ELSE s.site_id||' d '||c.day||' '||(  CASE   WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value   END  )   END   AS identity,  CASE   WHEN typeof(e.token)='blob' THEN s.site_id||':'||substr(lower(hex(substr(e.token,1,16))),1,8)||'-'||substr(lower(hex(substr(e.token,1,16))),9,4)||'-'||substr(lower(hex(substr(e.token,1,16))),13,4)||'-'||substr(lower(hex(substr(e.token,1,16))),17,4)||'-'||substr(lower(hex(substr(e.token,1,16))),21,12)||CAST(substr(e.token,17) AS TEXT) ELSE e.token   END   AS id
 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context JOIN vane_raw_sites s ON s.site=e.site
 LEFT JOIN vane_raw_details d ON d.raw_id=e.raw_id LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor;

CREATE TRIGGER vane_raw_event_insert INSTEAD OF INSERT ON vane_raw_events BEGIN
 INSERT OR IGNORE INTO vane_raw_groups(context,at_offset,visit_id)
 SELECT NEW.context,NEW.at_offset,NEW.visit_id WHERE NOT EXISTS(SELECT 1 FROM vane_raw_occurrences WHERE site=NEW.site AND token=NEW.token);
 INSERT INTO vane_raw_occurrences(raw_id,site,token,group_id)
 VALUES(NEW.raw_id,NEW.site,NEW.token,COALESCE((SELECT group_id FROM vane_raw_occurrences WHERE site=NEW.site AND token=NEW.token),(SELECT group_id FROM vane_raw_groups WHERE context=NEW.context AND (at_offset IS NULL)=(NEW.at_offset IS NULL) AND coalesce(at_offset,0)=coalesce(NEW.at_offset,0) AND (visit_id IS NULL)=(NEW.visit_id IS NULL) AND coalesce(visit_id,0)=coalesce(NEW.visit_id,0))));
 END ;
CREATE TRIGGER vane_raw_event_update INSTEAD OF UPDATE ON vane_raw_events BEGIN
 INSERT OR IGNORE INTO vane_raw_groups(context,at_offset,visit_id) VALUES(NEW.context,NEW.at_offset,( CASE  WHEN NEW.context IS NOT OLD.context OR NEW.at_offset IS NOT OLD.at_offset OR NEW.site IS NOT OLD.site OR NEW.token IS NOT OLD.token THEN NULL ELSE NEW.visit_id  END ));
 UPDATE vane_raw_occurrences SET raw_id=NEW.raw_id,site=NEW.site,token=NEW.token,
 group_id=(SELECT group_id FROM vane_raw_groups WHERE context=NEW.context AND (at_offset IS NULL)=(NEW.at_offset IS NULL) AND coalesce(at_offset,0)=coalesce(NEW.at_offset,0) AND (visit_id IS NULL)=(( CASE  WHEN NEW.context IS NOT OLD.context OR NEW.at_offset IS NOT OLD.at_offset OR NEW.site IS NOT OLD.site OR NEW.token IS NOT OLD.token THEN NULL ELSE NEW.visit_id  END ) IS NULL) AND coalesce(visit_id,0)=coalesce(( CASE  WHEN NEW.context IS NOT OLD.context OR NEW.at_offset IS NOT OLD.at_offset OR NEW.site IS NOT OLD.site OR NEW.token IS NOT OLD.token THEN NULL ELSE NEW.visit_id  END ),0)) WHERE raw_id=OLD.raw_id;
 END ;
CREATE TRIGGER vane_raw_event_delete INSTEAD OF DELETE ON vane_raw_events BEGIN
 DELETE FROM vane_raw_occurrences WHERE raw_id=OLD.raw_id;
 END ;

CREATE TRIGGER vane_raw_insert INSTEAD OF INSERT ON vane_events BEGIN
 INSERT OR IGNORE INTO vane_raw_sites(site_id) SELECT NEW.site_id WHERE NOT EXISTS(SELECT 1 FROM vane_raw_events WHERE site=(SELECT site FROM vane_raw_sites WHERE site_id=NEW.site_id) AND token=  CASE   WHEN substr(NEW.id,1,length(NEW.site_id)+1)=NEW.site_id||':' AND length(substr(NEW.id,length(NEW.site_id)+2,36))=36 AND length(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-',''))=32 AND replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','') NOT GLOB '*[^0-9a-f]*' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),9,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),14,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),19,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),24,1)='-' THEN unhex(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','')||hex(substr(NEW.id,length(NEW.site_id)+38))) ELSE NEW.id   END  );
 INSERT OR IGNORE INTO vane_raw_identities(value) SELECT   CASE   WHEN length(NEW.visitor)=64 AND NEW.visitor NOT GLOB '*[^0-9a-f]*' THEN unhex(NEW.visitor) ELSE NEW.visitor   END   WHERE NEW.visitor IS NOT NULL AND NOT EXISTS(SELECT 1 FROM vane_raw_events WHERE site=(SELECT site FROM vane_raw_sites WHERE site_id=NEW.site_id) AND token=  CASE   WHEN substr(NEW.id,1,length(NEW.site_id)+1)=NEW.site_id||':' AND length(substr(NEW.id,length(NEW.site_id)+2,36))=36 AND length(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-',''))=32 AND replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','') NOT GLOB '*[^0-9a-f]*' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),9,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),14,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),19,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),24,1)='-' THEN unhex(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','')||hex(substr(NEW.id,length(NEW.site_id)+38))) ELSE NEW.id   END  );
 INSERT OR IGNORE INTO vane_raw_identities(value) SELECT   CASE   WHEN length(NEW.consented_visitor)=64 AND NEW.consented_visitor NOT GLOB '*[^0-9a-f]*' THEN unhex(NEW.consented_visitor) ELSE NEW.consented_visitor   END   WHERE NEW.consented_visitor IS NOT NULL AND NOT EXISTS(SELECT 1 FROM vane_raw_events WHERE site=(SELECT site FROM vane_raw_sites WHERE site_id=NEW.site_id) AND token=  CASE   WHEN substr(NEW.id,1,length(NEW.site_id)+1)=NEW.site_id||':' AND length(substr(NEW.id,length(NEW.site_id)+2,36))=36 AND length(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-',''))=32 AND replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','') NOT GLOB '*[^0-9a-f]*' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),9,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),14,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),19,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),24,1)='-' THEN unhex(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','')||hex(substr(NEW.id,length(NEW.site_id)+38))) ELSE NEW.id   END  );
 INSERT OR IGNORE INTO vane_raw_contexts(site,day,kind,dimensions,visitor,consented_visitor,consented_created_at,consented_expires_at) SELECT (SELECT site FROM vane_raw_sites WHERE site_id=NEW.site_id),NEW.day,NEW.kind,json_array(NEW.path,NEW.source,NEW.campaign,NEW.hostname,NEW.device,NEW.browser,NEW.browser_version,NEW.os,NEW.os_version,NEW.screen,NEW.channel,NEW.referrer,NEW.utm_source,NEW.utm_medium,NEW.utm_term,NEW.utm_content,NEW.country,NEW.region,NEW.city,NEW.metro_code,NEW.search,NEW.transport,NEW.consent,NEW.sample_rate,NEW.import_job,NEW.paid_click,NEW.query),(SELECT identity FROM vane_raw_identities WHERE value=  CASE   WHEN length(NEW.visitor)=64 AND NEW.visitor NOT GLOB '*[^0-9a-f]*' THEN unhex(NEW.visitor) ELSE NEW.visitor   END  ),(SELECT identity FROM vane_raw_identities WHERE value=  CASE   WHEN length(NEW.consented_visitor)=64 AND NEW.consented_visitor NOT GLOB '*[^0-9a-f]*' THEN unhex(NEW.consented_visitor) ELSE NEW.consented_visitor   END  ),NEW.consented_created_at,NEW.consented_expires_at WHERE NOT EXISTS(SELECT 1 FROM vane_raw_events WHERE site=(SELECT site FROM vane_raw_sites WHERE site_id=NEW.site_id) AND token=  CASE   WHEN substr(NEW.id,1,length(NEW.site_id)+1)=NEW.site_id||':' AND length(substr(NEW.id,length(NEW.site_id)+2,36))=36 AND length(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-',''))=32 AND replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','') NOT GLOB '*[^0-9a-f]*' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),9,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),14,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),19,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),24,1)='-' THEN unhex(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','')||hex(substr(NEW.id,length(NEW.site_id)+38))) ELSE NEW.id   END  );
 INSERT OR IGNORE INTO vane_raw_groups(context,at_offset,visit_id)
 SELECT (SELECT context FROM vane_raw_contexts WHERE site IS (SELECT site FROM vane_raw_sites WHERE site_id=NEW.site_id) AND day IS NEW.day AND kind IS NEW.kind AND dimensions IS json_array(NEW.path,NEW.source,NEW.campaign,NEW.hostname,NEW.device,NEW.browser,NEW.browser_version,NEW.os,NEW.os_version,NEW.screen,NEW.channel,NEW.referrer,NEW.utm_source,NEW.utm_medium,NEW.utm_term,NEW.utm_content,NEW.country,NEW.region,NEW.city,NEW.metro_code,NEW.search,NEW.transport,NEW.consent,NEW.sample_rate,NEW.import_job,NEW.paid_click,NEW.query) AND visitor IS (SELECT identity FROM vane_raw_identities WHERE value=  CASE   WHEN length(NEW.visitor)=64 AND NEW.visitor NOT GLOB '*[^0-9a-f]*' THEN unhex(NEW.visitor) ELSE NEW.visitor   END  ) AND consented_visitor IS (SELECT identity FROM vane_raw_identities WHERE value=  CASE   WHEN length(NEW.consented_visitor)=64 AND NEW.consented_visitor NOT GLOB '*[^0-9a-f]*' THEN unhex(NEW.consented_visitor) ELSE NEW.consented_visitor   END  ) AND consented_created_at IS NEW.consented_created_at AND consented_expires_at IS NEW.consented_expires_at),NEW.at-coalesce(unixepoch(NEW.day)*1000,0),NULL WHERE NOT EXISTS(SELECT 1 FROM vane_raw_occurrences WHERE site=(SELECT site FROM vane_raw_sites WHERE site_id=NEW.site_id) AND token= CASE   WHEN substr(NEW.id,1,length(NEW.site_id)+1)=NEW.site_id||':' AND length(substr(NEW.id,length(NEW.site_id)+2,36))=36 AND length(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-',''))=32 AND replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','') NOT GLOB '*[^0-9a-f]*' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),9,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),14,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),19,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),24,1)='-' THEN unhex(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','')||hex(substr(NEW.id,length(NEW.site_id)+38))) ELSE NEW.id   END );
 INSERT INTO vane_raw_occurrences(site,token,group_id)
 VALUES((SELECT site FROM vane_raw_sites WHERE site_id=NEW.site_id), CASE   WHEN substr(NEW.id,1,length(NEW.site_id)+1)=NEW.site_id||':' AND length(substr(NEW.id,length(NEW.site_id)+2,36))=36 AND length(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-',''))=32 AND replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','') NOT GLOB '*[^0-9a-f]*' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),9,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),14,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),19,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),24,1)='-' THEN unhex(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','')||hex(substr(NEW.id,length(NEW.site_id)+38))) ELSE NEW.id   END ,COALESCE((SELECT group_id FROM vane_raw_occurrences WHERE site=(SELECT site FROM vane_raw_sites WHERE site_id=NEW.site_id) AND token= CASE   WHEN substr(NEW.id,1,length(NEW.site_id)+1)=NEW.site_id||':' AND length(substr(NEW.id,length(NEW.site_id)+2,36))=36 AND length(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-',''))=32 AND replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','') NOT GLOB '*[^0-9a-f]*' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),9,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),14,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),19,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),24,1)='-' THEN unhex(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','')||hex(substr(NEW.id,length(NEW.site_id)+38))) ELSE NEW.id   END ),(SELECT group_id FROM vane_raw_groups WHERE context=(SELECT context FROM vane_raw_contexts WHERE site IS (SELECT site FROM vane_raw_sites WHERE site_id=NEW.site_id) AND day IS NEW.day AND kind IS NEW.kind AND dimensions IS json_array(NEW.path,NEW.source,NEW.campaign,NEW.hostname,NEW.device,NEW.browser,NEW.browser_version,NEW.os,NEW.os_version,NEW.screen,NEW.channel,NEW.referrer,NEW.utm_source,NEW.utm_medium,NEW.utm_term,NEW.utm_content,NEW.country,NEW.region,NEW.city,NEW.metro_code,NEW.search,NEW.transport,NEW.consent,NEW.sample_rate,NEW.import_job,NEW.paid_click,NEW.query) AND visitor IS (SELECT identity FROM vane_raw_identities WHERE value=  CASE   WHEN length(NEW.visitor)=64 AND NEW.visitor NOT GLOB '*[^0-9a-f]*' THEN unhex(NEW.visitor) ELSE NEW.visitor   END  ) AND consented_visitor IS (SELECT identity FROM vane_raw_identities WHERE value=  CASE   WHEN length(NEW.consented_visitor)=64 AND NEW.consented_visitor NOT GLOB '*[^0-9a-f]*' THEN unhex(NEW.consented_visitor) ELSE NEW.consented_visitor   END  ) AND consented_created_at IS NEW.consented_created_at AND consented_expires_at IS NEW.consented_expires_at) AND (at_offset IS NULL)=(NEW.at-coalesce(unixepoch(NEW.day)*1000,0) IS NULL) AND coalesce(at_offset,0)=coalesce(NEW.at-coalesce(unixepoch(NEW.day)*1000,0),0) AND (visit_id IS NULL)=(NULL IS NULL) AND coalesce(visit_id,0)=coalesce(NULL,0))));
 INSERT INTO vane_raw_details(raw_id,engaged_at,scroll,lcp,inp,cls,load_ms)
 SELECT (SELECT raw_id FROM vane_raw_events WHERE site=(SELECT site FROM vane_raw_sites WHERE site_id=NEW.site_id) AND token=  CASE   WHEN substr(NEW.id,1,length(NEW.site_id)+1)=NEW.site_id||':' AND length(substr(NEW.id,length(NEW.site_id)+2,36))=36 AND length(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-',''))=32 AND replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','') NOT GLOB '*[^0-9a-f]*' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),9,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),14,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),19,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),24,1)='-' THEN unhex(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','')||hex(substr(NEW.id,length(NEW.site_id)+38))) ELSE NEW.id   END  ),NEW.engaged_at,NEW.scroll,NEW.lcp,NEW.inp,NEW.cls,NEW.load_ms WHERE (changes()>0) AND (NEW.engaged_at IS NOT NULL OR NEW.scroll IS NOT NULL OR NEW.lcp IS NOT NULL OR NEW.inp IS NOT NULL OR NEW.cls IS NOT NULL OR NEW.load_ms IS NOT NULL)
 ON CONFLICT(raw_id) DO UPDATE SET engaged_at=excluded.engaged_at,scroll=excluded.scroll,lcp=excluded.lcp,inp=excluded.inp,cls=excluded.cls,load_ms=excluded.load_ms;
  END  ;

CREATE TRIGGER vane_raw_update INSTEAD OF UPDATE ON vane_events BEGIN
 INSERT OR IGNORE INTO vane_raw_sites(site_id) SELECT NEW.site_id WHERE 1;
 INSERT OR IGNORE INTO vane_raw_identities(value) SELECT   CASE   WHEN length(NEW.visitor)=64 AND NEW.visitor NOT GLOB '*[^0-9a-f]*' THEN unhex(NEW.visitor) ELSE NEW.visitor   END   WHERE NEW.visitor IS NOT NULL AND 1;
 INSERT OR IGNORE INTO vane_raw_identities(value) SELECT   CASE   WHEN length(NEW.consented_visitor)=64 AND NEW.consented_visitor NOT GLOB '*[^0-9a-f]*' THEN unhex(NEW.consented_visitor) ELSE NEW.consented_visitor   END   WHERE NEW.consented_visitor IS NOT NULL AND 1;
 INSERT OR IGNORE INTO vane_raw_contexts(site,day,kind,dimensions,visitor,consented_visitor,consented_created_at,consented_expires_at) SELECT (SELECT site FROM vane_raw_sites WHERE site_id=NEW.site_id),NEW.day,NEW.kind,json_array(NEW.path,NEW.source,NEW.campaign,NEW.hostname,NEW.device,NEW.browser,NEW.browser_version,NEW.os,NEW.os_version,NEW.screen,NEW.channel,NEW.referrer,NEW.utm_source,NEW.utm_medium,NEW.utm_term,NEW.utm_content,NEW.country,NEW.region,NEW.city,NEW.metro_code,NEW.search,NEW.transport,NEW.consent,NEW.sample_rate,NEW.import_job,NEW.paid_click,NEW.query),(SELECT identity FROM vane_raw_identities WHERE value=  CASE   WHEN length(NEW.visitor)=64 AND NEW.visitor NOT GLOB '*[^0-9a-f]*' THEN unhex(NEW.visitor) ELSE NEW.visitor   END  ),(SELECT identity FROM vane_raw_identities WHERE value=  CASE   WHEN length(NEW.consented_visitor)=64 AND NEW.consented_visitor NOT GLOB '*[^0-9a-f]*' THEN unhex(NEW.consented_visitor) ELSE NEW.consented_visitor   END  ),NEW.consented_created_at,NEW.consented_expires_at WHERE 1;
 UPDATE vane_raw_events SET site=(SELECT site FROM vane_raw_sites WHERE site_id=NEW.site_id),token=  CASE   WHEN substr(NEW.id,1,length(NEW.site_id)+1)=NEW.site_id||':' AND length(substr(NEW.id,length(NEW.site_id)+2,36))=36 AND length(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-',''))=32 AND replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','') NOT GLOB '*[^0-9a-f]*' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),9,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),14,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),19,1)='-' AND substr(substr(NEW.id,length(NEW.site_id)+2,36),24,1)='-' THEN unhex(replace(substr(NEW.id,length(NEW.site_id)+2,36),'-','')||hex(substr(NEW.id,length(NEW.site_id)+38))) ELSE NEW.id   END  ,context=(SELECT context FROM vane_raw_contexts WHERE site IS (SELECT site FROM vane_raw_sites WHERE site_id=NEW.site_id) AND day IS NEW.day AND kind IS NEW.kind AND dimensions IS json_array(NEW.path,NEW.source,NEW.campaign,NEW.hostname,NEW.device,NEW.browser,NEW.browser_version,NEW.os,NEW.os_version,NEW.screen,NEW.channel,NEW.referrer,NEW.utm_source,NEW.utm_medium,NEW.utm_term,NEW.utm_content,NEW.country,NEW.region,NEW.city,NEW.metro_code,NEW.search,NEW.transport,NEW.consent,NEW.sample_rate,NEW.import_job,NEW.paid_click,NEW.query) AND visitor IS (SELECT identity FROM vane_raw_identities WHERE value=  CASE   WHEN length(NEW.visitor)=64 AND NEW.visitor NOT GLOB '*[^0-9a-f]*' THEN unhex(NEW.visitor) ELSE NEW.visitor   END  ) AND consented_visitor IS (SELECT identity FROM vane_raw_identities WHERE value=  CASE   WHEN length(NEW.consented_visitor)=64 AND NEW.consented_visitor NOT GLOB '*[^0-9a-f]*' THEN unhex(NEW.consented_visitor) ELSE NEW.consented_visitor   END  ) AND consented_created_at IS NEW.consented_created_at AND consented_expires_at IS NEW.consented_expires_at),at_offset=NEW.at-coalesce(unixepoch(NEW.day)*1000,0) WHERE raw_id=OLD._raw_id;
 INSERT INTO vane_raw_details(raw_id,engaged_at,scroll,lcp,inp,cls,load_ms)
 SELECT OLD._raw_id,NEW.engaged_at,NEW.scroll,NEW.lcp,NEW.inp,NEW.cls,NEW.load_ms WHERE (1) AND (NEW.engaged_at IS NOT NULL OR NEW.scroll IS NOT NULL OR NEW.lcp IS NOT NULL OR NEW.inp IS NOT NULL OR NEW.cls IS NOT NULL OR NEW.load_ms IS NOT NULL)
 ON CONFLICT(raw_id) DO UPDATE SET engaged_at=excluded.engaged_at,scroll=excluded.scroll,lcp=excluded.lcp,inp=excluded.inp,cls=excluded.cls,load_ms=excluded.load_ms;
 DELETE FROM vane_raw_details WHERE raw_id=OLD._raw_id AND NEW.engaged_at IS NULL AND NEW.scroll IS NULL AND NEW.lcp IS NULL AND NEW.inp IS NULL AND NEW.cls IS NULL AND NEW.load_ms IS NULL;
  END  ;

CREATE TRIGGER vane_raw_delete INSTEAD OF DELETE ON vane_events BEGIN
 DELETE FROM vane_raw_events WHERE raw_id=OLD._raw_id;
  END  ;

CREATE TRIGGER vane_raw_context_gc AFTER DELETE ON vane_raw_contexts BEGIN
 DELETE FROM vane_raw_identities WHERE identity IN (OLD.visitor,OLD.consented_visitor)
 AND NOT EXISTS(SELECT 1 FROM vane_raw_contexts WHERE visitor=identity OR consented_visitor=identity);
 DELETE FROM vane_raw_sites WHERE site=OLD.site AND NOT EXISTS(SELECT 1 FROM vane_raw_contexts WHERE site=OLD.site) AND NOT EXISTS(SELECT 1 FROM vane_raw_events WHERE site=OLD.site);
  END  ;

CREATE TRIGGER vane_visit_rebuild_chain AFTER INSERT ON vane_visit_rebuild BEGIN
 DELETE FROM vane_visit_facts WHERE site=NEW.site AND day=NEW.day AND visitor=NEW.visitor;
 INSERT INTO vane_visit_rebuild_pages(raw_id,context,run,at,id,engaged_at,scroll,identity,on_page,first,last)
 SELECT raw_id,context,MIN(raw_id) OVER (PARTITION BY run),at,id,engaged_at,scroll,identity,
   CASE   WHEN next_at IS NOT NULL AND next_at-at<=gap THEN next_at-at ELSE COALESCE(engaged_at-at,0)   END  ,first,  CASE   WHEN next_at IS NULL OR next_at-at>gap THEN 1 ELSE 0   END  
 FROM (SELECT *,SUM(first) OVER (ORDER BY at,id ROWS UNBOUNDED PRECEDING) AS run FROM (
 SELECT *,  CASE   WHEN prev_at IS NULL OR at-prev_at>gap THEN 1 ELSE 0   END   AS first FROM (
 SELECT r.*,(COALESCE((SELECT json_extract(d.value,'$.minutes') FROM vane_sites s,json_each(s.config_json,'$.definitions') d WHERE s.id=r.site_id AND json_extract(d.value,'$.metric')='visit-timeout' AND json_extract(d.value,'$.from')<=r.day ORDER BY json_extract(d.value,'$.from') DESC,CAST(d.key AS INTEGER) DESC LIMIT 1),30)*60000) AS gap,LAG(at) OVER (ORDER BY at,id) AS prev_at,LEAD(at) OVER (ORDER BY at,id) AS next_at FROM vane_visit_raw r
 WHERE r.site=NEW.site AND r.day=NEW.day AND r.visitor=NEW.visitor AND r.kind='pageview' AND r.at IS NOT NULL)));
 INSERT INTO vane_visit_facts(site,day,visitor,first_raw,last_raw,started,last_at,last_signal,pages,engaged,identity,first_on_page)
 SELECT NEW.site,NEW.day,NEW.visitor,MAX(  CASE   WHEN first=1 THEN raw_id   END  ),MAX(  CASE   WHEN last=1 THEN raw_id   END  ),MIN(at),MAX(at),MAX(MAX(at,COALESCE(engaged_at,at))),COUNT(*),SUM(engaged_at IS NOT NULL),MAX(identity),MAX(  CASE   WHEN first=1 THEN on_page   END  )
 FROM vane_visit_rebuild_pages GROUP BY run;
 UPDATE vane_raw_events SET visit_id=(SELECT f.visit FROM vane_visit_rebuild_pages p JOIN vane_visit_rebuild_pages anchor ON anchor.run=p.run AND anchor.first=1 JOIN vane_visit_facts f ON f.first_raw=anchor.raw_id WHERE p.raw_id=vane_raw_events.raw_id)
 WHERE raw_id IN (SELECT raw_id FROM vane_visit_rebuild_pages);
 INSERT INTO vane_visit_page_frequencies(visit,context,on_page,scroll,n)
 SELECT e.visit_id,p.context,p.on_page,COALESCE(p.scroll,-1),COUNT(*) FROM vane_visit_rebuild_pages p JOIN vane_raw_events e ON e.raw_id=p.raw_id GROUP BY e.visit_id,p.context,p.on_page,COALESCE(p.scroll,-1);
 DELETE FROM vane_visit_rebuild_pages;
 DELETE FROM vane_visit_dirty WHERE site=NEW.site AND day=NEW.day AND visitor=NEW.visitor;
 DELETE FROM vane_visit_rebuild WHERE site=NEW.site AND day=NEW.day AND visitor=NEW.visitor;
  END  ;

CREATE TRIGGER vane_visit_details_insert AFTER INSERT ON vane_raw_details BEGIN
INSERT INTO vane_visit_performance(context,metric,value,n) SELECT e.context,'lcp',NEW.lcp,1 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context WHERE e.raw_id=NEW.raw_id AND c.kind='pageview' AND NEW.lcp IS NOT NULL ON CONFLICT(context,metric,value) DO UPDATE SET n=n+1;
INSERT INTO vane_visit_performance(context,metric,value,n) SELECT e.context,'inp',NEW.inp,1 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context WHERE e.raw_id=NEW.raw_id AND c.kind='pageview' AND NEW.inp IS NOT NULL ON CONFLICT(context,metric,value) DO UPDATE SET n=n+1;
INSERT INTO vane_visit_performance(context,metric,value,n) SELECT e.context,'cls',NEW.cls,1 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context WHERE e.raw_id=NEW.raw_id AND c.kind='pageview' AND NEW.cls IS NOT NULL ON CONFLICT(context,metric,value) DO UPDATE SET n=n+1;
INSERT INTO vane_visit_performance(context,metric,value,n) SELECT e.context,'load',NEW.load_ms,1 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context WHERE e.raw_id=NEW.raw_id AND c.kind='pageview' AND NEW.load_ms IS NOT NULL ON CONFLICT(context,metric,value) DO UPDATE SET n=n+1;
INSERT INTO vane_visit_measured(context,n) SELECT e.context,1 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context WHERE e.raw_id=NEW.raw_id AND c.kind='pageview' AND (NEW.lcp IS NOT NULL OR NEW.inp IS NOT NULL OR NEW.cls IS NOT NULL OR NEW.load_ms IS NOT NULL) ON CONFLICT(context) DO UPDATE SET n=n+1;
INSERT INTO vane_visit_work(raw_id,action,old_engaged,old_scroll,new_engaged,new_scroll)
 SELECT r.raw_id,'detail',NULL,NULL,NEW.engaged_at,NEW.scroll FROM vane_visit_raw r
 WHERE r.raw_id=NEW.raw_id AND r.visit_id IS NOT NULL AND r.kind='pageview' AND r.at IS NOT NULL AND r.visitor IS NOT NULL
 AND NOT EXISTS(SELECT 1 FROM vane_visit_dirty d WHERE d.site=r.site AND d.day=r.day AND d.visitor=r.visitor)
 AND (NULL IS NOT NEW.engaged_at OR NULL IS NOT NEW.scroll);
  END  ;

CREATE TRIGGER vane_visit_details_update AFTER UPDATE ON vane_raw_details BEGIN
UPDATE vane_visit_performance SET n=n-1 WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND metric='lcp' AND value=OLD.lcp;
UPDATE vane_visit_performance SET n=n-1 WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND metric='inp' AND value=OLD.inp;
UPDATE vane_visit_performance SET n=n-1 WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND metric='cls' AND value=OLD.cls;
UPDATE vane_visit_performance SET n=n-1 WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND metric='load' AND value=OLD.load_ms;
DELETE FROM vane_visit_performance WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND n=0;
UPDATE vane_visit_measured SET n=n-1 WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND (OLD.lcp IS NOT NULL OR OLD.inp IS NOT NULL OR OLD.cls IS NOT NULL OR OLD.load_ms IS NOT NULL);
DELETE FROM vane_visit_measured WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND n=0;
INSERT INTO vane_visit_performance(context,metric,value,n) SELECT e.context,'lcp',NEW.lcp,1 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context WHERE e.raw_id=NEW.raw_id AND c.kind='pageview' AND NEW.lcp IS NOT NULL ON CONFLICT(context,metric,value) DO UPDATE SET n=n+1;
INSERT INTO vane_visit_performance(context,metric,value,n) SELECT e.context,'inp',NEW.inp,1 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context WHERE e.raw_id=NEW.raw_id AND c.kind='pageview' AND NEW.inp IS NOT NULL ON CONFLICT(context,metric,value) DO UPDATE SET n=n+1;
INSERT INTO vane_visit_performance(context,metric,value,n) SELECT e.context,'cls',NEW.cls,1 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context WHERE e.raw_id=NEW.raw_id AND c.kind='pageview' AND NEW.cls IS NOT NULL ON CONFLICT(context,metric,value) DO UPDATE SET n=n+1;
INSERT INTO vane_visit_performance(context,metric,value,n) SELECT e.context,'load',NEW.load_ms,1 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context WHERE e.raw_id=NEW.raw_id AND c.kind='pageview' AND NEW.load_ms IS NOT NULL ON CONFLICT(context,metric,value) DO UPDATE SET n=n+1;
INSERT INTO vane_visit_measured(context,n) SELECT e.context,1 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context WHERE e.raw_id=NEW.raw_id AND c.kind='pageview' AND (NEW.lcp IS NOT NULL OR NEW.inp IS NOT NULL OR NEW.cls IS NOT NULL OR NEW.load_ms IS NOT NULL) ON CONFLICT(context) DO UPDATE SET n=n+1;
INSERT INTO vane_visit_work(raw_id,action,old_engaged,old_scroll,new_engaged,new_scroll)
 SELECT r.raw_id,'detail',OLD.engaged_at,OLD.scroll,NEW.engaged_at,NEW.scroll FROM vane_visit_raw r
 WHERE r.raw_id=NEW.raw_id AND r.visit_id IS NOT NULL AND r.kind='pageview' AND r.at IS NOT NULL AND r.visitor IS NOT NULL
 AND NOT EXISTS(SELECT 1 FROM vane_visit_dirty d WHERE d.site=r.site AND d.day=r.day AND d.visitor=r.visitor)
 AND (OLD.engaged_at IS NOT NEW.engaged_at OR OLD.scroll IS NOT NEW.scroll);
  END  ;

CREATE TRIGGER vane_visit_details_delete BEFORE DELETE ON vane_raw_details BEGIN
UPDATE vane_visit_performance SET n=n-1 WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND metric='lcp' AND value=OLD.lcp;
UPDATE vane_visit_performance SET n=n-1 WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND metric='inp' AND value=OLD.inp;
UPDATE vane_visit_performance SET n=n-1 WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND metric='cls' AND value=OLD.cls;
UPDATE vane_visit_performance SET n=n-1 WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND metric='load' AND value=OLD.load_ms;
DELETE FROM vane_visit_performance WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND n=0;
UPDATE vane_visit_measured SET n=n-1 WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND (OLD.lcp IS NOT NULL OR OLD.inp IS NOT NULL OR OLD.cls IS NOT NULL OR OLD.load_ms IS NOT NULL);
DELETE FROM vane_visit_measured WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND n=0;
INSERT INTO vane_visit_work(raw_id,action,old_engaged,old_scroll,new_engaged,new_scroll)
 SELECT r.raw_id,'detail',OLD.engaged_at,OLD.scroll,NULL,NULL FROM vane_visit_raw r
 WHERE r.raw_id=OLD.raw_id AND r.visit_id IS NOT NULL AND r.kind='pageview' AND r.at IS NOT NULL AND r.visitor IS NOT NULL
 AND NOT EXISTS(SELECT 1 FROM vane_visit_dirty d WHERE d.site=r.site AND d.day=r.day AND d.visitor=r.visitor)
 AND (OLD.engaged_at IS NOT NULL OR OLD.scroll IS NOT NULL);
  END  ;

CREATE TRIGGER vane_visit_append AFTER INSERT ON vane_visit_work WHEN NEW.action='insert' BEGIN
 UPDATE vane_visit_work SET
 (site,context,day,visitor,site_id,at,at_offset,token,identity)=(
 SELECT e.site,e.context,c.day,c.visitor,s.site_id,e.at_offset+unixepoch(c.day)*1000,e.at_offset,e.token,
   CASE   WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||(  CASE   WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value   END  )
 ELSE s.site_id||' d '||c.day||' '||(  CASE   WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value   END  )   END  
 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context
 JOIN vane_raw_sites s ON s.site=e.site
 LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor
 LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor
 WHERE e.raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_work SET prev=(SELECT (SELECT candidate.raw_id FROM vane_raw_contexts cx JOIN vane_raw_events candidate ON candidate.raw_id=COALESCE(
 (SELECT tied.raw_id FROM vane_raw_events tied
  WHERE tied.context=cx.context AND tied.at_offset=r.at_offset AND tied.token<r.token
  ORDER BY tied.token DESC LIMIT 1),
 (SELECT adjacent.raw_id FROM vane_raw_events adjacent
  WHERE adjacent.context=cx.context AND adjacent.at_offset=(
   SELECT bucket.at_offset FROM vane_raw_events bucket
   WHERE bucket.context=cx.context AND bucket.at_offset<r.at_offset
   ORDER BY bucket.at_offset DESC LIMIT 1)
  ORDER BY adjacent.token DESC LIMIT 1))
 WHERE cx.site=r.site AND cx.day=r.day AND cx.visitor=r.visitor AND cx.kind='pageview'
 ORDER BY candidate.at_offset DESC,candidate.token DESC LIMIT 1) FROM vane_visit_work r WHERE r.raw_id=NEW.raw_id),next=(SELECT (SELECT candidate.raw_id FROM vane_raw_contexts cx JOIN vane_raw_events candidate ON candidate.raw_id=COALESCE(
 (SELECT tied.raw_id FROM vane_raw_events tied
  WHERE tied.context=cx.context AND tied.at_offset=r.at_offset AND tied.token>r.token
  ORDER BY tied.token ASC LIMIT 1),
 (SELECT adjacent.raw_id FROM vane_raw_events adjacent
  WHERE adjacent.context=cx.context AND adjacent.at_offset=(
   SELECT bucket.at_offset FROM vane_raw_events bucket
   WHERE bucket.context=cx.context AND bucket.at_offset>r.at_offset
   ORDER BY bucket.at_offset ASC LIMIT 1)
  ORDER BY adjacent.token ASC LIMIT 1))
 WHERE cx.site=r.site AND cx.day=r.day AND cx.visitor=r.visitor AND cx.kind='pageview'
 ORDER BY candidate.at_offset ASC,candidate.token ASC LIMIT 1) FROM vane_visit_work r WHERE r.raw_id=NEW.raw_id),gap=(SELECT (COALESCE((SELECT json_extract(d.value,'$.minutes') FROM vane_sites s,json_each(s.config_json,'$.definitions') d WHERE s.id=r.site_id AND json_extract(d.value,'$.metric')='visit-timeout' AND json_extract(d.value,'$.from')<=r.day ORDER BY json_extract(d.value,'$.from') DESC,CAST(d.key AS INTEGER) DESC LIMIT 1),30)*60000) FROM vane_visit_work r WHERE r.raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_work SET
 (prev_at,prev_context,prev_engaged,prev_scroll,prev_visit,next_at,next_visit)=(
 SELECT p.at_offset+unixepoch(pc.day)*1000,p.context,pd.engaged_at,pd.scroll,p.visit_id,
 n.at_offset+unixepoch(nc.day)*1000,n.visit_id
 FROM vane_visit_work w
 LEFT JOIN vane_raw_events p ON p.raw_id=w.prev
 LEFT JOIN vane_raw_contexts pc ON pc.context=p.context
 LEFT JOIN vane_raw_details pd ON pd.raw_id=p.raw_id
 LEFT JOIN vane_raw_events n ON n.raw_id=w.next
 LEFT JOIN vane_raw_contexts nc ON nc.context=n.context
 WHERE w.raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_work SET left_visit=   CASE    WHEN (SELECT prev FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT prev_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT prev_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)    END   ,right_visit=   CASE    WHEN (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)    END   ,
 old_on_page=   CASE    WHEN (SELECT prev FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT prev_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT prev_at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE COALESCE((SELECT prev_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT prev_at FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)    END    WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_page_frequencies SET n=n-1 WHERE visit=(SELECT prev_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND context=(SELECT prev_context FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND on_page=(SELECT old_on_page FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND scroll=COALESCE((SELECT prev_scroll FROM vane_visit_work WHERE raw_id=NEW.raw_id),-1) AND (SELECT prev FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL;
 DELETE FROM vane_visit_page_frequencies WHERE visit=(SELECT prev_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND n=0;
 INSERT INTO vane_visit_page_frequencies(visit,context,on_page,scroll,n)
 SELECT (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id),context,on_page,scroll,n FROM vane_visit_page_frequencies WHERE visit=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)!=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)
 ON CONFLICT(visit,context,on_page,scroll) DO UPDATE SET n=n+excluded.n;
 UPDATE vane_visit_facts SET pages=pages+(SELECT pages FROM vane_visit_facts WHERE visit=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)),
 engaged=engaged+(SELECT engaged FROM vane_visit_facts WHERE visit=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)),
 last_at=(SELECT last_at FROM vane_visit_facts WHERE visit=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)),last_raw=(SELECT last_raw FROM vane_visit_facts WHERE visit=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)),
 last_signal=MAX(last_signal,(SELECT last_signal FROM vane_visit_facts WHERE visit=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id))),identity=MAX(identity,(SELECT identity FROM vane_visit_facts WHERE visit=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)))
 WHERE visit=(SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)!=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id);
 UPDATE vane_raw_events SET visit_id=(SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) WHERE visit_id=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)!=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id);
 DELETE FROM vane_visit_facts WHERE visit=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT left_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id)!=(SELECT right_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id);
 INSERT INTO vane_visit_facts(site,day,visitor,first_raw,last_raw,started,last_at,last_signal,pages,engaged,identity,first_on_page)
 SELECT site,day,visitor,raw_id,raw_id,at,at,at,0,0,identity,0 FROM vane_visit_work WHERE raw_id=NEW.raw_id AND left_visit IS NULL AND right_visit IS NULL;
 UPDATE vane_visit_work SET visit=COALESCE(left_visit,right_visit,last_insert_rowid()) WHERE raw_id=NEW.raw_id;
 UPDATE vane_raw_events SET visit_id=(SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 INSERT INTO vane_visit_page_frequencies(visit,context,on_page,scroll,n) SELECT (SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT context FROM vane_visit_work WHERE raw_id=NEW.raw_id),   CASE    WHEN (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)    END   ,COALESCE((SELECT new_scroll FROM vane_visit_work WHERE raw_id=NEW.raw_id),-1),1 WHERE 1
 ON CONFLICT(visit,context,on_page,scroll) DO UPDATE SET n=n+1;
 INSERT INTO vane_visit_page_frequencies(visit,context,on_page,scroll,n) SELECT (SELECT prev_visit FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT prev_context FROM vane_visit_work WHERE raw_id=NEW.raw_id),   CASE    WHEN (SELECT prev FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT prev_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT prev_at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE (SELECT old_on_page FROM vane_visit_work WHERE raw_id=NEW.raw_id)    END   ,COALESCE((SELECT prev_scroll FROM vane_visit_work WHERE raw_id=NEW.raw_id),-1),1 WHERE (SELECT prev FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL
 ON CONFLICT(visit,context,on_page,scroll) DO UPDATE SET n=n+1;
 UPDATE vane_visit_facts SET pages=pages+1,engaged=engaged+((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL),
 first_on_page=   CASE    WHEN ((SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT token FROM vane_visit_work WHERE raw_id=NEW.raw_id))<(started,(SELECT token FROM vane_raw_events WHERE raw_id=first_raw)) OR pages=0 THEN    CASE    WHEN (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)    END   
 WHEN first_raw=(SELECT prev FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND (SELECT prev FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT prev_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT prev_at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE first_on_page    END   ,
 first_raw=   CASE    WHEN ((SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT token FROM vane_visit_work WHERE raw_id=NEW.raw_id))<(started,(SELECT token FROM vane_raw_events WHERE raw_id=first_raw)) THEN NEW.raw_id ELSE first_raw    END   ,
 last_raw=   CASE    WHEN ((SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT token FROM vane_visit_work WHERE raw_id=NEW.raw_id))>(last_at,(SELECT token FROM vane_raw_events WHERE raw_id=last_raw)) THEN NEW.raw_id ELSE last_raw    END   ,
 started=MIN(started,(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)),last_at=MAX(last_at,(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)),last_signal=MAX(last_signal,(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id))),identity=MAX(identity,(SELECT identity FROM vane_visit_work WHERE raw_id=NEW.raw_id))
 WHERE visit=(SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id);
 DELETE FROM vane_visit_work WHERE raw_id=NEW.raw_id;
   END   ;

CREATE TRIGGER vane_visit_detail_change AFTER INSERT ON vane_visit_work WHEN NEW.action='detail' BEGIN
 UPDATE vane_visit_work SET
 (site,context,day,visitor,site_id,at,at_offset,token,identity)=(
 SELECT e.site,e.context,c.day,c.visitor,s.site_id,e.at_offset+unixepoch(c.day)*1000,e.at_offset,e.token,
   CASE   WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||(  CASE   WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value   END  )
 ELSE s.site_id||' d '||c.day||' '||(  CASE   WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value   END  )   END  
 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context
 JOIN vane_raw_sites s ON s.site=e.site
 LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor
 LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor
 WHERE e.raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_work SET next=(SELECT (SELECT candidate.raw_id FROM vane_raw_contexts cx JOIN vane_raw_events candidate ON candidate.raw_id=COALESCE(
 (SELECT tied.raw_id FROM vane_raw_events tied
  WHERE tied.context=cx.context AND tied.at_offset=r.at_offset AND tied.token>r.token
  ORDER BY tied.token ASC LIMIT 1),
 (SELECT adjacent.raw_id FROM vane_raw_events adjacent
  WHERE adjacent.context=cx.context AND adjacent.at_offset=(
   SELECT bucket.at_offset FROM vane_raw_events bucket
   WHERE bucket.context=cx.context AND bucket.at_offset>r.at_offset
   ORDER BY bucket.at_offset ASC LIMIT 1)
  ORDER BY adjacent.token ASC LIMIT 1))
 WHERE cx.site=r.site AND cx.day=r.day AND cx.visitor=r.visitor AND cx.kind='pageview'
 ORDER BY candidate.at_offset ASC,candidate.token ASC LIMIT 1) FROM vane_visit_work r WHERE r.raw_id=NEW.raw_id),gap=(SELECT (COALESCE((SELECT json_extract(d.value,'$.minutes') FROM vane_sites s,json_each(s.config_json,'$.definitions') d WHERE s.id=r.site_id AND json_extract(d.value,'$.metric')='visit-timeout' AND json_extract(d.value,'$.from')<=r.day ORDER BY json_extract(d.value,'$.from') DESC,CAST(d.key AS INTEGER) DESC LIMIT 1),30)*60000) FROM vane_visit_work r WHERE r.raw_id=NEW.raw_id),visit=(SELECT visit_id FROM vane_raw_events WHERE raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_work SET
 (prev_at,prev_context,prev_engaged,prev_scroll,prev_visit,next_at,next_visit)=(
 SELECT p.at_offset+unixepoch(pc.day)*1000,p.context,pd.engaged_at,pd.scroll,p.visit_id,
 n.at_offset+unixepoch(nc.day)*1000,n.visit_id
 FROM vane_visit_work w
 LEFT JOIN vane_raw_events p ON p.raw_id=w.prev
 LEFT JOIN vane_raw_contexts pc ON pc.context=p.context
 LEFT JOIN vane_raw_details pd ON pd.raw_id=p.raw_id
 LEFT JOIN vane_raw_events n ON n.raw_id=w.next
 LEFT JOIN vane_raw_contexts nc ON nc.context=n.context
 WHERE w.raw_id=NEW.raw_id) WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_work SET old_on_page=   CASE    WHEN (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE COALESCE(old_engaged-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)    END    WHERE raw_id=NEW.raw_id;
 UPDATE vane_visit_page_frequencies SET n=n-1 WHERE visit=(SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND context=(SELECT context FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND on_page=(SELECT old_on_page FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND scroll=COALESCE((SELECT old_scroll FROM vane_visit_work WHERE raw_id=NEW.raw_id),-1) AND 1;
 DELETE FROM vane_visit_page_frequencies WHERE visit=(SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id) AND n=0;
 INSERT INTO vane_visit_page_frequencies(visit,context,on_page,scroll,n) SELECT (SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT context FROM vane_visit_work WHERE raw_id=NEW.raw_id),   CASE    WHEN (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)    END   ,COALESCE((SELECT new_scroll FROM vane_visit_work WHERE raw_id=NEW.raw_id),-1),1 WHERE 1
 ON CONFLICT(visit,context,on_page,scroll) DO UPDATE SET n=n+1;
 UPDATE vane_visit_facts SET engaged=engaged+((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL)-((SELECT old_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL),
 first_on_page=   CASE    WHEN first_raw=NEW.raw_id THEN    CASE    WHEN (SELECT next FROM vane_visit_work WHERE raw_id=NEW.raw_id) IS NOT NULL AND (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)<=(SELECT gap FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN (SELECT next_at FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id)-(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)    END    ELSE first_on_page    END   ,
 last_signal=   CASE    WHEN (SELECT old_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id)=last_signal AND COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id),0)<(SELECT old_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id) THEN
 (SELECT MAX(MAX((r.at_offset+unixepoch(signal_context.day)*1000),COALESCE(   CASE    WHEN r.raw_id=NEW.raw_id THEN (SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id) ELSE signal_details.engaged_at    END   ,(r.at_offset+unixepoch(signal_context.day)*1000)))) FROM vane_raw_events r JOIN vane_raw_contexts signal_context ON signal_context.context=r.context LEFT JOIN vane_raw_details signal_details ON signal_details.raw_id=r.raw_id WHERE r.visit_id=vane_visit_facts.visit)
 ELSE MAX(last_signal,COALESCE((SELECT new_engaged FROM vane_visit_work WHERE raw_id=NEW.raw_id),(SELECT at FROM vane_visit_work WHERE raw_id=NEW.raw_id)))    END    WHERE visit=(SELECT visit FROM vane_visit_work WHERE raw_id=NEW.raw_id);
 DELETE FROM vane_visit_work WHERE raw_id=NEW.raw_id;
   END   ;

CREATE TRIGGER vane_visit_raw_delete BEFORE DELETE ON vane_raw_occurrences BEGIN
 INSERT OR IGNORE INTO vane_visit_dirty(site,day,visitor) SELECT site,day,visitor FROM vane_raw_contexts WHERE context=(SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id) AND kind='pageview' AND visitor IS NOT NULL;
 DELETE FROM vane_raw_details WHERE raw_id=OLD.raw_id;
  END  ;

CREATE TRIGGER vane_visit_raw_rewrite BEFORE UPDATE OF group_id,site,token ON vane_raw_occurrences WHEN (SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id) IS NOT (SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) OR (SELECT at_offset FROM vane_raw_groups WHERE group_id=OLD.group_id) IS NOT (SELECT at_offset FROM vane_raw_groups WHERE group_id=NEW.group_id) OR OLD.site IS NOT NEW.site OR OLD.token IS NOT NEW.token BEGIN
 INSERT OR IGNORE INTO vane_visit_legacy(site,day,visitor)
 SELECT site,day,visitor FROM vane_raw_contexts WHERE context=(SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id)
 AND kind='pageview' AND visitor IS NOT NULL AND typeof(NEW.token)!='blob';
 INSERT OR IGNORE INTO vane_visit_dirty(site,day,visitor) SELECT site,day,visitor FROM vane_raw_contexts WHERE context IN ((SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id),(SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id)) AND kind='pageview' AND visitor IS NOT NULL;
  END  ;

CREATE TRIGGER vane_visit_perf_context_before BEFORE UPDATE OF group_id ON vane_raw_occurrences WHEN (SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id) IS NOT (SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) BEGIN
UPDATE vane_visit_performance SET n=n-1 WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND metric='lcp' AND value=(SELECT lcp FROM vane_raw_details WHERE raw_id=OLD.raw_id);
UPDATE vane_visit_performance SET n=n-1 WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND metric='inp' AND value=(SELECT inp FROM vane_raw_details WHERE raw_id=OLD.raw_id);
UPDATE vane_visit_performance SET n=n-1 WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND metric='cls' AND value=(SELECT cls FROM vane_raw_details WHERE raw_id=OLD.raw_id);
UPDATE vane_visit_performance SET n=n-1 WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND metric='load' AND value=(SELECT load_ms FROM vane_raw_details WHERE raw_id=OLD.raw_id);
DELETE FROM vane_visit_performance WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND n=0;
UPDATE vane_visit_measured SET n=n-1 WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND ((SELECT lcp FROM vane_raw_details WHERE raw_id=OLD.raw_id) IS NOT NULL OR (SELECT inp FROM vane_raw_details WHERE raw_id=OLD.raw_id) IS NOT NULL OR (SELECT cls FROM vane_raw_details WHERE raw_id=OLD.raw_id) IS NOT NULL OR (SELECT load_ms FROM vane_raw_details WHERE raw_id=OLD.raw_id) IS NOT NULL);
DELETE FROM vane_visit_measured WHERE context=(SELECT context FROM vane_raw_events WHERE raw_id=OLD.raw_id) AND n=0;
  END  ;

CREATE TRIGGER vane_raw_group_required_insert BEFORE INSERT ON vane_raw_occurrences
 WHEN NEW.group_id IS NULL BEGIN SELECT RAISE(ABORT,'Raw occurrence requires an exact metadata group');  END ;

CREATE TRIGGER vane_raw_group_required_update BEFORE UPDATE ON vane_raw_occurrences
 WHEN NEW.group_id IS NULL BEGIN SELECT RAISE(ABORT,'Raw occurrence requires an exact metadata group');  END ;

CREATE TRIGGER vane_raw_occurrence_insert AFTER INSERT ON vane_raw_occurrences BEGIN
INSERT INTO vane_analytics_cells(site_id,day,kind,cell,n,timed,consented)
 SELECT site_id,day,kind,cell,1,timed,consented FROM (SELECT s.site_id,c.day,c.kind,json_remove(c.dimensions,'$[26]','$[25]') AS cell,
   CASE   WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||  CASE   WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value   END   ELSE s.site_id||' d '||c.day||' '||  CASE   WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value   END     END   AS identity,
 c.visitor,(SELECT at_offset FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT NULL AS timed,c.consented_visitor IS NOT NULL AS consented
 FROM vane_raw_contexts c JOIN vane_raw_sites s ON s.site=c.site
 LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor
 WHERE c.context=(SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) AND NOT EXISTS(SELECT 1 FROM vane_visit_bulk_scope)) WHERE 1
 ON CONFLICT(site_id,day,kind,cell) DO UPDATE SET n=n+1,timed=timed+excluded.timed,consented=consented+excluded.consented;
 INSERT INTO vane_analytics_identities(site_id,day,kind,cell,identity,n)
 SELECT site_id,day,kind,cell,identity,1 FROM (SELECT s.site_id,c.day,c.kind,json_remove(c.dimensions,'$[26]','$[25]') AS cell,
   CASE   WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||  CASE   WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value   END   ELSE s.site_id||' d '||c.day||' '||  CASE   WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value   END     END   AS identity,
 c.visitor,(SELECT at_offset FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT NULL AS timed,c.consented_visitor IS NOT NULL AS consented
 FROM vane_raw_contexts c JOIN vane_raw_sites s ON s.site=c.site
 LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor
 WHERE c.context=(SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) AND NOT EXISTS(SELECT 1 FROM vane_visit_bulk_scope)) WHERE visitor IS NOT NULL
 ON CONFLICT(site_id,day,kind,cell,identity) DO UPDATE SET n=n+1;
INSERT OR IGNORE INTO vane_visit_legacy(site,day,visitor) SELECT site,day,visitor FROM vane_raw_contexts WHERE context=(SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) AND (SELECT at_offset FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM vane_visit_bulk_scope) AND kind='pageview' AND visitor IS NOT NULL AND typeof(NEW.token)!='blob';
 INSERT OR IGNORE INTO vane_visit_dirty(site,day,visitor) SELECT c.site,c.day,c.visitor FROM vane_raw_contexts c JOIN vane_visit_legacy l USING(site,day,visitor) WHERE c.context=(SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) AND (SELECT at_offset FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM vane_visit_bulk_scope) AND c.kind='pageview' AND c.visitor IS NOT NULL;
 INSERT INTO vane_visit_work(raw_id,action,new_engaged,new_scroll) SELECT r.raw_id,'insert',r.engaged_at,r.scroll FROM vane_visit_raw r WHERE r.raw_id=NEW.raw_id AND r.at_offset IS NOT NULL AND NOT EXISTS(SELECT 1 FROM vane_visit_bulk_scope) AND r.kind='pageview' AND r.visitor IS NOT NULL
 AND NOT EXISTS(SELECT 1 FROM vane_visit_dirty d WHERE d.site=r.site AND d.day=r.day AND d.visitor=r.visitor);
INSERT INTO vane_visit_work(raw_id,action)
 SELECT NEW.raw_id,'bulk' FROM vane_raw_contexts WHERE context=(SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) AND EXISTS(SELECT 1 FROM vane_visit_bulk_scope) AND kind='pageview';
 END ;

CREATE TRIGGER vane_raw_occurrence_delete AFTER DELETE ON vane_raw_occurrences BEGIN
UPDATE vane_analytics_identities SET n=n-1 WHERE (site_id,day,kind,cell)=(SELECT site_id,day,kind,cell FROM (SELECT s.site_id,c.day,c.kind,json_remove(c.dimensions,'$[26]','$[25]') AS cell,
   CASE   WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||  CASE   WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value   END   ELSE s.site_id||' d '||c.day||' '||  CASE   WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value   END     END   AS identity,
 c.visitor,(SELECT at_offset FROM vane_raw_groups WHERE group_id=OLD.group_id) IS NOT NULL AS timed,c.consented_visitor IS NOT NULL AS consented
 FROM vane_raw_contexts c JOIN vane_raw_sites s ON s.site=c.site
 LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor
 WHERE c.context=(SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id))) AND identity=(SELECT identity FROM (SELECT s.site_id,c.day,c.kind,json_remove(c.dimensions,'$[26]','$[25]') AS cell,
   CASE   WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||  CASE   WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value   END   ELSE s.site_id||' d '||c.day||' '||  CASE   WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value   END     END   AS identity,
 c.visitor,(SELECT at_offset FROM vane_raw_groups WHERE group_id=OLD.group_id) IS NOT NULL AS timed,c.consented_visitor IS NOT NULL AS consented
 FROM vane_raw_contexts c JOIN vane_raw_sites s ON s.site=c.site
 LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor
 WHERE c.context=(SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id))) AND (SELECT visitor FROM (SELECT s.site_id,c.day,c.kind,json_remove(c.dimensions,'$[26]','$[25]') AS cell,
   CASE   WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||  CASE   WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value   END   ELSE s.site_id||' d '||c.day||' '||  CASE   WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value   END     END   AS identity,
 c.visitor,(SELECT at_offset FROM vane_raw_groups WHERE group_id=OLD.group_id) IS NOT NULL AS timed,c.consented_visitor IS NOT NULL AS consented
 FROM vane_raw_contexts c JOIN vane_raw_sites s ON s.site=c.site
 LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor
 WHERE c.context=(SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id))) IS NOT NULL;
 DELETE FROM vane_analytics_identities WHERE (site_id,day,kind,cell)=(SELECT site_id,day,kind,cell FROM (SELECT s.site_id,c.day,c.kind,json_remove(c.dimensions,'$[26]','$[25]') AS cell,
   CASE   WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||  CASE   WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value   END   ELSE s.site_id||' d '||c.day||' '||  CASE   WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value   END     END   AS identity,
 c.visitor,(SELECT at_offset FROM vane_raw_groups WHERE group_id=OLD.group_id) IS NOT NULL AS timed,c.consented_visitor IS NOT NULL AS consented
 FROM vane_raw_contexts c JOIN vane_raw_sites s ON s.site=c.site
 LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor
 WHERE c.context=(SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id))) AND n=0;
 UPDATE vane_analytics_cells SET n=n-1,timed=timed-((SELECT at_offset FROM vane_raw_groups WHERE group_id=OLD.group_id) IS NOT NULL),consented=consented-(SELECT consented FROM (SELECT s.site_id,c.day,c.kind,json_remove(c.dimensions,'$[26]','$[25]') AS cell,
   CASE   WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||  CASE   WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value   END   ELSE s.site_id||' d '||c.day||' '||  CASE   WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value   END     END   AS identity,
