 INSERT INTO vane_analytics_cells(site_id,day,kind,cell,n,timed,consented)
 SELECT site_id,day,kind,cell,1,timed,consented FROM (SELECT s.site_id,c.day,c.kind,json_remove(c.dimensions,'$[26]','$[25]') AS cell,
   CASE   WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||  CASE   WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value   END   ELSE s.site_id||' d '||c.day||' '||  CASE   WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value   END     END   AS identity,
 c.visitor,(SELECT at_offset FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT NULL AS timed,c.consented_visitor IS NOT NULL AS consented
 FROM vane_raw_contexts c JOIN vane_raw_sites s ON s.site=c.site
 LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor
 WHERE c.context=(SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) AND ((SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT (SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id) OR (SELECT at_offset FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT (SELECT at_offset FROM vane_raw_groups WHERE group_id=OLD.group_id))) WHERE 1
 ON CONFLICT(site_id,day,kind,cell) DO UPDATE SET n=n+1,timed=timed+excluded.timed,consented=consented+excluded.consented;
 INSERT INTO vane_analytics_identities(site_id,day,kind,cell,identity,n)
 SELECT site_id,day,kind,cell,identity,1 FROM (SELECT s.site_id,c.day,c.kind,json_remove(c.dimensions,'$[26]','$[25]') AS cell,
   CASE   WHEN c.consented_visitor IS NOT NULL THEN s.site_id||' c '||  CASE   WHEN typeof(ci.value)='blob' THEN lower(hex(ci.value)) ELSE ci.value   END   ELSE s.site_id||' d '||c.day||' '||  CASE   WHEN typeof(vi.value)='blob' THEN lower(hex(vi.value)) ELSE vi.value   END     END   AS identity,
 c.visitor,(SELECT at_offset FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT NULL AS timed,c.consented_visitor IS NOT NULL AS consented
 FROM vane_raw_contexts c JOIN vane_raw_sites s ON s.site=c.site
 LEFT JOIN vane_raw_identities vi ON vi.identity=c.visitor LEFT JOIN vane_raw_identities ci ON ci.identity=c.consented_visitor
 WHERE c.context=(SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) AND ((SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT (SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id) OR (SELECT at_offset FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT (SELECT at_offset FROM vane_raw_groups WHERE group_id=OLD.group_id))) WHERE visitor IS NOT NULL
 ON CONFLICT(site_id,day,kind,cell,identity) DO UPDATE SET n=n+1;
INSERT INTO vane_visit_performance(context,metric,value,n) SELECT e.context,'lcp',(SELECT lcp FROM vane_raw_details WHERE raw_id=NEW.raw_id),1 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context WHERE e.raw_id=NEW.raw_id AND (SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT (SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id) AND c.kind='pageview' AND (SELECT lcp FROM vane_raw_details WHERE raw_id=NEW.raw_id) IS NOT NULL ON CONFLICT(context,metric,value) DO UPDATE SET n=n+1;
INSERT INTO vane_visit_performance(context,metric,value,n) SELECT e.context,'inp',(SELECT inp FROM vane_raw_details WHERE raw_id=NEW.raw_id),1 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context WHERE e.raw_id=NEW.raw_id AND (SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT (SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id) AND c.kind='pageview' AND (SELECT inp FROM vane_raw_details WHERE raw_id=NEW.raw_id) IS NOT NULL ON CONFLICT(context,metric,value) DO UPDATE SET n=n+1;
INSERT INTO vane_visit_performance(context,metric,value,n) SELECT e.context,'cls',(SELECT cls FROM vane_raw_details WHERE raw_id=NEW.raw_id),1 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context WHERE e.raw_id=NEW.raw_id AND (SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT (SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id) AND c.kind='pageview' AND (SELECT cls FROM vane_raw_details WHERE raw_id=NEW.raw_id) IS NOT NULL ON CONFLICT(context,metric,value) DO UPDATE SET n=n+1;
INSERT INTO vane_visit_performance(context,metric,value,n) SELECT e.context,'load',(SELECT load_ms FROM vane_raw_details WHERE raw_id=NEW.raw_id),1 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context WHERE e.raw_id=NEW.raw_id AND (SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT (SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id) AND c.kind='pageview' AND (SELECT load_ms FROM vane_raw_details WHERE raw_id=NEW.raw_id) IS NOT NULL ON CONFLICT(context,metric,value) DO UPDATE SET n=n+1;
INSERT INTO vane_visit_measured(context,n) SELECT e.context,1 FROM vane_raw_events e JOIN vane_raw_contexts c ON c.context=e.context WHERE e.raw_id=NEW.raw_id AND (SELECT context FROM vane_raw_groups WHERE group_id=NEW.group_id) IS NOT (SELECT context FROM vane_raw_groups WHERE group_id=OLD.group_id) AND c.kind='pageview' AND ((SELECT lcp FROM vane_raw_details WHERE raw_id=NEW.raw_id) IS NOT NULL OR (SELECT inp FROM vane_raw_details WHERE raw_id=NEW.raw_id) IS NOT NULL OR (SELECT cls FROM vane_raw_details WHERE raw_id=NEW.raw_id) IS NOT NULL OR (SELECT load_ms FROM vane_raw_details WHERE raw_id=NEW.raw_id) IS NOT NULL) ON CONFLICT(context) DO UPDATE SET n=n+1;
DELETE FROM vane_raw_groups WHERE group_id=OLD.group_id
 AND NOT EXISTS(SELECT 1 FROM vane_raw_occurrences WHERE group_id=OLD.group_id);
 END ;

CREATE TRIGGER vane_raw_group_gc AFTER DELETE ON vane_raw_groups BEGIN
 DELETE FROM vane_raw_contexts WHERE context=OLD.context
 AND NOT EXISTS(SELECT 1 FROM vane_raw_groups WHERE context=OLD.context);
 END ;
